input.new_string:
    it('should prefer gzip over deflate when q values are equal', async () => {
      const app = buildAppDefault()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'gzip;q=0.5, deflate;q=0.5' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('gzip')
    })
  })

  describe('Brotli Support', () => {
    const isBrotliSupported = (() => {
      try {
        new CompressionStream('br' as CompressionFormat)
        return true
      } catch {
        return false
      }
    })()

    const buildAppDefault = () => {
      const app = new Hono()
      app.use('*', compress())
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      app.get('/strong-etag', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        c.header('ETag', '"strong-etag"')
        return c.text('a'.repeat(1024))
      })
      return app
    }

    describe.skipIf(!isBrotliSupported)('when runtime supports brotli', () => {
      it('should compress with brotli when Accept-Encoding is br', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('br')
        expect(res.headers.get('Content-Length')).toBeNull()
        expect((await res.arrayBuffer()).byteLength).toBeLessThan(1024)
      })

      it('should prefer brotli over gzip and deflate', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'gzip, deflate, br' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('br')
      })

      it('should prefer brotli over gzip when both have q=1', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'br, gzip' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('br')
      })

      it('should fall back to gzip when br has q=0', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'br;q=0, gzip' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('gzip')
      })

      it('should convert strong ETag to weak ETag when compressing with brotli', async () => {
        const res = await buildAppDefault().request('/strong-etag', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('br')
        expect(res.headers.get('ETag')).toBe('W/"strong-etag"')
      })

      it('should honor explicit encoding: br option', async () => {
        const app = new Hono()
        app.use('*', compress({ encoding: 'br' }))
        app.get('/large', (c) => {
          c.header('Content-Type', 'text/plain')
          c.header('Content-Length', '1024')
          return c.text('a'.repeat(1024))
        })
        const res = await app.request('/large', {
          headers: { 'Accept-Encoding': 'br, gzip' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('br')
      })

      it('should respect contentTypeFilter when compressing with brotli', async () => {
        const app = new Hono()
        app.use('*', compress({ contentTypeFilter: /^application\/json/, threshold: 0 }))
        app.get('/json', (c) => c.json({ data: 'a'.repeat(1024) }))
        app.get('/text', (c) => c.text('a'.repeat(1024)))

        const jsonRes = await app.request('/json', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(jsonRes.headers.get('Content-Encoding')).toBe('br')

        const textRes = await app.request('/text', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(textRes.headers.get('Content-Encoding')).toBeNull()
      })

      it('should respect threshold when compressing with brotli', async () => {
        const app = new Hono()
        app.use('*', compress())
        app.get('/small', (c) => {
          c.header('Content-Type', 'text/plain')
          c.header('Content-Length', '5')
          return c.text('small')
        })
        const res = await app.request('/small', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(res.headers.get('Content-Encoding')).toBeNull()
      })
    })

    describe.skipIf(isBrotliSupported)('when runtime does not support brotli', () => {
      it('should fall back to gzip when Accept-Encoding includes both br and gzip', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'br, gzip' },
        })
        expect(res.headers.get('Content-Encoding')).toBe('gzip')
      })

      it('should not compress when only br is in Accept-Encoding', async () => {
        const res = await buildAppDefault().request('/large', {
          headers: { 'Accept-Encoding': 'br' },
        })
        expect(res.headers.get('Content-Encoding')).toBeNull()
      })

      it('should not compress when encoding: br is requested but unsupported', async () => {
        const app = new Hono()
        app.use('*', compress({ encoding: 'br' }))
        app.get('/large', (c) => {
          c.header('Content-Type', 'text/plain')
          c.header('Content-Length', '1024')
          return c.text('a'.repeat(1024))
        })
        const res = await app.request('/large', {
          headers: { 'Accept-Encoding': 'br, gzip, deflate' },
        })
        expect(res.headers.get('Content-Encoding')).toBeNull()
      })
    })
  })
})

